	import { get } from 'svelte/store';
	import { onMount, getContext } from 'svelte';
	import { goto } from '$app/navigation';
	import { WEBUI_NAME, config, user } from '$lib/stores';
	import { getUsers } from '$lib/apis/users';
	import { getModels } from '$lib/apis';
	import { getFunctions } from '$lib/apis/functions';
	import { getAllFeedbacks } from '$lib/apis/evaluations';
	import type { i18n as i18nType } from 'i18next';
	import type { Writable } from 'svelte/store';

	const i18n: Writable<i18nType> = getContext<Writable<i18nType>>('i18n');

	let loaded = $state(false);
	let userCount = $state(0);
	let modelCount = $state(0);
	let functionCount = $state(0);
	let feedbackCount = $state(0);

	type QuickLink = {
		label: string;
		description: string;
		href: string;
		icon: 'users' | 'functions' | 'evaluations' | 'settings';
	};

	const quickLinks: QuickLink[] = [
		{
			label: 'Users',
			description: 'Manage users, roles and permissions',
			href: '/admin/users',
			icon: 'users'
		},
		{
			label: 'Evaluations',
			description: 'View leaderboard and feedback history',
			href: '/admin/evaluations',
			icon: 'evaluations'
		},
		{
			label: 'Functions',
			description: 'Create and manage custom functions',
			href: '/admin/functions',
			icon: 'functions'
		},
		{
			label: 'Settings',
			description: 'Configure connections, models and more',
			href: '/admin/settings',
			icon: 'settings'
		}
	];

	onMount(async () => {
		if (get(user)?.role !== 'admin') {
			await goto('/');
			return;
		}

		const [usersData, modelsData, functionsData, feedbacksData] = await Promise.all([
			getUsers(localStorage.token).catch(() => []),
			getModels(localStorage.token).catch(() => []),
			getFunctions(localStorage.token).catch(() => []),
			getAllFeedbacks(localStorage.token).catch(() => [])
		]);

		userCount = usersData.length;
		modelCount = modelsData.filter((m) => m?.owned_by !== 'arena' && !(m?.info?.meta?.hidden ?? false))
			.length;
		functionCount = functionsData.length;
		feedbackCount = feedbacksData.length;
		loaded = true;
	});
</script>

